// Pages advanced mode: this worker serves the whole site.
//
// Two jobs. It answers /api/ask by calling Claude with a key held at the edge,
// and it sets the security headers on everything else, because Pages ignores
// `_headers` for responses a worker returns. Both the header list and this
// file are generated by build.py from one declaration, so they cannot drift.

const SECURITY_HEADERS = __SECURITY_HEADERS__;

const MODEL = "claude-haiku-4-5";
const MAX_QUESTION = 500;
const MAX_CONTEXT = 60000;

// The site carries no authentication of its own, so Cloudflare Access is the
// only thing standing between these endpoints and anyone who reaches the
// worker - and behind /api/ask sits a metered API key. Access sends a signed
// JWT in this header on every request it admits, but the header being present
// proves nothing: a request that reaches the worker without passing Access - on
// a hostname the Access application does not cover, such as a per-deployment
// preview URL - can carry any header it likes. So the token is verified here,
// against the team's published signing keys and this application's audience
// tag, and a request whose token does not verify is refused.
const ACCESS_HEADER = "cf-access-jwt-assertion";

// Access rotates its signing keys, so they are fetched rather than pinned, and
// held per isolate rather than fetched on every request. A key id the cache has
// not seen is what a rotation looks like from here, so it earns a refetch - at
// most once a minute, so a stream of made-up key ids cannot turn every request
// into a fetch.
const KEYS_TTL_MS = 60 * 60 * 1000;
const UNKNOWN_KEY_REFETCH_MS = 60 * 1000;
let signingKeys = { byKid: new Map(), fetchedAt: 0 };

function base64UrlBytes(part) {
  const base64 = part.replace(/-/g, "+").replace(/_/g, "/");
  return Uint8Array.from(atob(base64.padEnd(Math.ceil(base64.length / 4) * 4, "=")), c => c.charCodeAt(0));
}

async function loadSigningKeys(teamDomain) {
  const response = await fetch(teamDomain + "/cdn-cgi/access/certs");
  if (!response.ok) throw new Error("Access signing keys answered " + response.status);
  const { keys } = await response.json();
  const byKid = new Map();
  // Only RS256 tokens are accepted below, so a key published for any other
  // algorithm could never verify one and is not imported.
  for (const jwk of keys.filter(k => k.alg === "RS256")) {
    byKid.set(
      jwk.kid,
      await crypto.subtle.importKey("jwk", jwk, { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["verify"])
    );
  }
  signingKeys = { byKid, fetchedAt: Date.now() };
}

// The token's claims, or null for any token Access did not issue to this
// application: malformed, another algorithm, an unknown key, a bad signature,
// another application's audience, another team, or outside its validity window.
// Throws only when the signing keys cannot be fetched, which is not the
// token's fault and is answered differently.
async function verifyAccessToken(token, env) {
  const parts = token.split(".");
  if (parts.length !== 3) return null;
  let header, claims, signature;
  try {
    header = JSON.parse(new TextDecoder().decode(base64UrlBytes(parts[0])));
    claims = JSON.parse(new TextDecoder().decode(base64UrlBytes(parts[1])));
    signature = base64UrlBytes(parts[2]);
  } catch {
    return null;
  }
  if (header.alg !== "RS256") return null;

  const age = Date.now() - signingKeys.fetchedAt;
  if (age > KEYS_TTL_MS || (!signingKeys.byKid.has(header.kid) && age > UNKNOWN_KEY_REFETCH_MS)) {
    await loadSigningKeys(env.ACCESS_TEAM_DOMAIN);
  }
  const key = signingKeys.byKid.get(header.kid);
  if (!key) return null;

  const signed = new TextEncoder().encode(parts[0] + "." + parts[1]);
  if (!(await crypto.subtle.verify("RSASSA-PKCS1-v1_5", key, signature, signed))) return null;

  const now = Date.now() / 1000;
  const audiences = Array.isArray(claims.aud) ? claims.aud : [claims.aud];
  if (!audiences.includes(env.ACCESS_AUD) || claims.iss !== env.ACCESS_TEAM_DOMAIN) return null;
  if (typeof claims.exp !== "number" || claims.exp <= now) return null;
  if (typeof claims.nbf === "number" && claims.nbf > now) return null;
  return claims;
}

function withSecurity(response) {
  const headers = new Headers(response.headers);
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) headers.set(name, value);
  return new Response(response.body, { status: response.status, headers });
}

function problem(status, message) {
  return new Response(JSON.stringify({ error: message }), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", ...SECURITY_HEADERS },
  });
}

async function ask(request, env) {
  if (request.method !== "POST") return problem(405, "Use POST.");
  if (!env.ANTHROPIC_API_KEY) {
    return problem(
      503,
      "No API key is configured. Run: wrangler pages secret put ANTHROPIC_API_KEY"
    );
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return problem(400, "Expected a JSON body.");
  }
  const question = typeof body.question === "string" ? body.question.trim() : "";
  const context = typeof body.context === "string" ? body.context : "";
  const cite = typeof body.cite === "string" ? body.cite : "";
  if (!question) return problem(400, "Ask a question.");
  if (question.length > MAX_QUESTION) return problem(400, "That question is too long.");
  if (!context) return problem(400, "No wiki pages were sent with that question.");
  if (context.length > MAX_CONTEXT) return problem(400, "Too many pages for one question.");

  // The pages are the reader's own wiki, but they are still text arriving in a
  // request body, so they are delimited and named as data rather than pasted
  // in as if they were instructions.
  const prompt =
    "You are answering from a compiled engineering wiki about Genesis, an AI fashion platform. " +
    "Use ONLY the pages below. " +
    cite +
    " If pages disagree, present both and name them; never average them into one confident answer. " +
    "Answer in plain prose, at most 200 words, no preamble.\n\n" +
    context +
    "\n\nQuestion: " +
    question;

  const upstream = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "anthropic-version": "2023-06-01",
      "x-api-key": env.ANTHROPIC_API_KEY,
    },
    body: JSON.stringify({
      model: MODEL,
      max_tokens: 1024,
      stream: true,
      messages: [{ role: "user", content: prompt }],
    }),
  });

  if (!upstream.ok) {
    const detail = await upstream.text().catch(() => "");
    return problem(
      upstream.status === 429 ? 429 : 502,
      upstream.status === 429
        ? "Rate limited upstream - wait a moment and ask again."
        : "The model call failed: " + detail.slice(0, 200)
    );
  }

  // Re-emit only the text deltas as plain text. The browser reads this with a
  // stream reader and appends; sending the raw Anthropic SSE would make the
  // page parse an event format it has no reason to know about.
  const decoder = new TextDecoder();
  const encoder = new TextEncoder();
  let buffered = "";
  const text = upstream.body.pipeThrough(
    new TransformStream({
      transform(chunk, controller) {
        buffered += decoder.decode(chunk, { stream: true });
        const lines = buffered.split("\n");
        buffered = lines.pop() ?? "";
        for (const line of lines) {
          if (!line.startsWith("data:")) continue;
          const payload = line.slice(5).trim();
          if (!payload || payload === "[DONE]") continue;
          try {
            const event = JSON.parse(payload);
            if (event.type === "content_block_delta" && event.delta?.type === "text_delta") {
              controller.enqueue(encoder.encode(event.delta.text));
            }
          } catch {
            // A partial event is normal at a chunk boundary; the tail stays in
            // `buffered` and parses on the next pass.
          }
        }
      },
    })
  );

  return new Response(text, {
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "cache-control": "no-store",
      ...SECURITY_HEADERS,
    },
  });
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
      ...SECURITY_HEADERS,
    },
  });
}

// Settings are stored one row per dotted path, so the shapes have to be
// flattened on the way in and rebuilt on the way out. Arrays are left whole:
// nothing in brain.config.json holds one, and splitting them into indexed keys
// would invent an ordering problem for a case that does not exist.
function flatten(value, prefix = "", into = {}) {
  for (const [key, inner] of Object.entries(value)) {
    const path = prefix ? prefix + "." + key : key;
    if (inner && typeof inner === "object" && !Array.isArray(inner)) flatten(inner, path, into);
    else into[path] = JSON.stringify(inner);
  }
  return into;
}

function unflatten(rows) {
  const out = {};
  for (const { key, value } of rows) {
    const parts = key.split(".");
    let node = out;
    for (const part of parts.slice(0, -1)) node = node[part] ??= {};
    try { node[parts.at(-1)] = JSON.parse(value); } catch { node[parts.at(-1)] = value; }
  }
  return out;
}

async function notes(request, env, url) {
  if (request.method === "GET") {
    // `?all=1` is how /brain:log sees what it has already filed; the page only
    // ever wants the queue.
    const showAll = url.searchParams.get("all") === "1";
    const { results } = await env.BRAIN_DB.prepare(
      showAll
        ? "SELECT id, text, created_at, filed_at FROM notes ORDER BY created_at DESC LIMIT 200"
        : "SELECT id, text, created_at, filed_at FROM notes WHERE filed_at IS NULL ORDER BY created_at DESC LIMIT 200"
    ).all();
    return json({ notes: results ?? [] });
  }

  if (request.method === "POST") {
    const body = await request.json().catch(() => null);
    const text = body && typeof body.text === "string" ? body.text.trim() : "";
    if (!text) return problem(400, "A note needs some text.");
    if (text.length > 4000) return problem(400, "That note is too long.");
    await env.BRAIN_DB.prepare("INSERT INTO notes (text, created_at) VALUES (?, ?)")
      .bind(text, new Date().toISOString())
      .run();
    return json({ ok: true }, 201);
  }

  return problem(405, "Use GET or POST.");
}

async function filed(request, env) {
  if (request.method !== "POST") return problem(405, "Use POST.");
  const body = await request.json().catch(() => null);
  const ids = Array.isArray(body?.ids) ? body.ids.filter(n => Number.isInteger(n)) : [];
  if (!ids.length) return problem(400, "Name the note ids that were filed.");
  // Marking, not deleting: a filed note stays as the record that it reached the
  // vault, and re-running a drain that half-finished cannot lose one.
  const marks = ids.map(() => "?").join(",");
  await env.BRAIN_DB.prepare(
    `UPDATE notes SET filed_at = ? WHERE id IN (${marks}) AND filed_at IS NULL`
  ).bind(new Date().toISOString(), ...ids).run();
  return json({ filed: ids.length });
}

async function settings(request, env) {
  if (request.method === "GET") {
    const { results } = await env.BRAIN_DB.prepare("SELECT key, value FROM settings").all();
    return json({ config: unflatten(results ?? []) });
  }

  if (request.method === "PUT") {
    const body = await request.json().catch(() => null);
    if (!body || typeof body.config !== "object" || body.config === null) {
      return problem(400, "Send the settings as {config: {...}}.");
    }
    const flat = Object.entries(flatten(body.config));
    if (flat.length > 200) return problem(400, "That is more settings than this holds.");
    const saved_at = new Date().toISOString();
    await env.BRAIN_DB.batch(
      flat.map(([key, value]) =>
        env.BRAIN_DB.prepare(
          "INSERT INTO settings (key, value, saved_at) VALUES (?, ?, ?) " +
          "ON CONFLICT(key) DO UPDATE SET value = excluded.value, saved_at = excluded.saved_at"
        ).bind(key, value, saved_at)
      )
    );
    return json({ saved: flat.length, saved_at });
  }

  return problem(405, "Use GET or PUT.");
}

// Live agent activity, read-only. The writer is `scripts/agent_activity.py`,
// called by hooks from wherever an agent runs; nothing writes through here.
// Open runs, runs not yet moved into `.claude/runs.tsv` however old they are -
// so a drain that has stopped working shows as runs piling up rather than as
// runs disappearing - and a week of finished ones for the page to merge with
// the ledger it already carries.
async function activity(request, env) {
  if (request.method !== "GET") return problem(405, "Use GET.");
  const { results } = await env.BRAIN_DB.prepare(
    "SELECT agent, session_id, agent_id, started_at, finished_at, target, outcome FROM agent_runs " +
      "WHERE finished_at IS NULL OR ledgered_at IS NULL " +
      "OR finished_at > strftime('%Y-%m-%dT%H:%M:%S', 'now', '-7 days') " +
      "ORDER BY COALESCE(finished_at, started_at) DESC LIMIT 500"
  ).all();
  // A dispatcher's runs are the tasks a session worked or the dispatcher
  // finished, chosen the same way: open, finished but not yet ledgered, or
  // ended within the week. The page turns each into a run.
  const tasks = await env.BRAIN_DB.prepare(
    "SELECT id, claimed_at, finished_at, outcome, closed_at FROM tasks " +
      "WHERE claimed_at IS NOT NULL AND (background_id IS NOT NULL OR finished_at IS NOT NULL) " +
      "AND ((finished_at IS NULL AND closed_at IS NULL) OR (finished_at IS NOT NULL AND ledgered_at IS NULL) " +
      "OR COALESCE(finished_at, closed_at) > strftime('%Y-%m-%dT%H:%M:%S', 'now', '-7 days')) " +
      "ORDER BY claimed_at DESC LIMIT 500"
  ).all();
  return json({ runs: results ?? [], tasks: tasks.results ?? [] });
}

// A timestamp as the scripts on the agents' machine write one - UTC, to the
// second, ISO 8601 - so a task's times sort and compare with the times they add.
function stamp() {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

// The dispatch queue. The page adds tasks and cancels ones nobody has picked up.
// Everything after that - claiming, the session's id, the outcome - is written
// by `scripts/task_queue.py` on the machine running the watcher. Who asked is the
// email in the verified Access token, never a value the page sends.
const MAX_TASK = 4000;
const AGENT_NAME = /^[a-z0-9-]{1,64}$/;
const REQUEST_ID = /^[A-Za-z0-9-]{8,64}$/;

async function tasks(request, env, url, claims) {
  if (request.method === "GET") {
    const [queue, watchers] = await env.BRAIN_DB.batch([
      env.BRAIN_DB.prepare(
        "SELECT id, text, assignee, created_by, created_at, claimed_at, claimed_by, background_id, " +
          "cancelled_at, finished_at, outcome, closed_at, closed_reason FROM tasks " +
          "ORDER BY created_at DESC, id DESC LIMIT 100"
      ),
      env.BRAIN_DB.prepare("SELECT host, started_at, last_seen_at FROM dispatchers ORDER BY last_seen_at DESC"),
    ]);
    return json({ tasks: queue.results ?? [], dispatchers: watchers.results ?? [] });
  }

  if (request.method === "POST") {
    const body = await request.json().catch(() => null);
    const text = typeof body?.text === "string" ? body.text.trim() : "";
    if (!text) return problem(400, "A task needs some text.");
    if (text.length > MAX_TASK) return problem(400, "That task is too long.");
    const assignee = body.assignee ?? null;
    if (assignee !== null && (typeof assignee !== "string" || !AGENT_NAME.test(assignee))) {
      return problem(400, "An assignee is an agent's name.");
    }
    const requestId = typeof body.request_id === "string" ? body.request_id : "";
    if (!REQUEST_ID.test(requestId)) return problem(400, "A task needs the request id the page generates for it.");
    // Only a person can dispatch work. A service token carries no email, and
    // nothing that runs unattended should be able to start an agent session.
    if (typeof claims.email !== "string" || !claims.email) {
      return problem(403, "Only a person signed in through Access can dispatch a task.");
    }
    // The page generates the request id once per task and sends it again on a
    // retry, so a submit that arrives twice is one task, answered with its id.
    const { results } = await env.BRAIN_DB.prepare(
      "INSERT INTO tasks (request_id, text, assignee, created_by, created_at) VALUES (?, ?, ?, ?, ?) " +
        "ON CONFLICT (request_id) DO NOTHING RETURNING id"
    ).bind(requestId, text, assignee, claims.email, stamp()).all();
    if (results?.length) return json({ id: results[0].id }, 201);
    // A repeat must be the same task. The same request id with other text or
    // another assignee is a change the stored task does not have, and answering
    // with the stored task's id would say it had been dispatched.
    const { results: existing } = await env.BRAIN_DB.prepare(
      "SELECT id, text, assignee FROM tasks WHERE request_id = ?"
    ).bind(requestId).all();
    const [stored] = existing;
    if (stored.text !== text || stored.assignee !== assignee) {
      return problem(409, "That request was already sent as a different task. Reload the page and dispatch it again.");
    }
    return json({ id: stored.id }, 200);
  }

  return problem(405, "Use GET or POST.");
}

async function cancelTask(request, env) {
  if (request.method !== "POST") return problem(405, "Use POST.");
  const body = await request.json().catch(() => null);
  if (!Number.isInteger(body?.id)) return problem(400, "Name the task to cancel.");
  // Only a task nobody has claimed. A claimed task already has a session
  // working on it, and marking the row cancelled would not stop that session.
  const { results } = await env.BRAIN_DB.prepare(
    "UPDATE tasks SET cancelled_at = ? WHERE id = ? AND claimed_at IS NULL AND cancelled_at IS NULL RETURNING id"
  ).bind(stamp(), body.id).all();
  if (!results?.length) return problem(409, "That task was already picked up or cancelled, or does not exist.");
  return json({ cancelled: body.id });
}

const ROUTES = {
  "/api/ask": ask,
  "/api/notes": notes,
  "/api/notes/filed": filed,
  "/api/config": settings,
  "/api/activity": activity,
  "/api/tasks": tasks,
  "/api/tasks/cancel": cancelTask,
};

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const route = ROUTES[url.pathname];
    if (!route) return withSecurity(await env.ASSETS.fetch(request));

    // One gate for every endpoint. Without the team and audience there is
    // nothing to verify a token against, and admitting on presence alone is
    // the hole this gate exists to close, so nothing answers.
    if (!env.ACCESS_TEAM_DOMAIN || !env.ACCESS_AUD) {
      return problem(503, "ACCESS_TEAM_DOMAIN and ACCESS_AUD are not set, so no request can be verified. Set them in wrangler.toml.");
    }
    const token = request.headers.get(ACCESS_HEADER);
    let claims;
    try {
      claims = token ? await verifyAccessToken(token, env) : null;
    } catch (error) {
      return problem(503, "Could not load the Access signing keys: " + String(error).slice(0, 200));
    }
    if (!claims) {
      return problem(403, "This request does not carry a valid Cloudflare Access token for this site.");
    }
    if (route !== ask && !env.BRAIN_DB) {
      return problem(503, "No database is bound. Create the D1 database and set database_id in wrangler.toml.");
    }
    try {
      return await route(request, env, url, claims);
    } catch (error) {
      return problem(500, "That request failed: " + String(error).slice(0, 200));
    }
  },
};
